for label in ('disabled_branch','uninvoked_function','quoted_text','heredoc'):
    def make_case(which):
        def check():
            m=t.nap();moi,xanh=m.doc_moi()
            log=(OUT/'real-moi'/which/'full.log').read_text().splitlines()
