        return check
    t.ca(make_case(label))
for label in ('check_url_int','check_url_list','steps_str','steps_list_scalar'):
    def make_case(which):
        def check():
            r=subprocess.run([sys.executable,'-B',str(OUT/'terminal_child.py'),which],capture_output=True)
